"""Milestone 2: discovery pool. Two kinds of rows, never mixed:
 - evidence_located: a named development found in a cached SEC annual report (url, sha256, sentence locator).
 - lead_unverified: a plausible development noted from general knowledge for later checking against a primary
   source. Leads carry NO facts to publish: names, dates and owners must be confirmed in Milestone 3 or dropped.
T = hotel_resort | food_led | other.  Route is a hypothesis until reviewed."""
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
sec = json.loads((ROOT / 'discovery/sec-candidates.json').read_text())['items']
def ev(ticker, needle):
    for o in sec:
        if o['ticker'] == ticker and needle in o['sentence']:
            return {'url': o['url'], 'sha256': o['sha256'], 'retrieved_at': o['retrieved_at'], 'form': o['form'], 'filed': o['filed'], 'locator': o['sentence'][:400], 'issuer': o['issuer'], 'cik': o['cik']}
    raise SystemExit(f'no sentence for {ticker}: {needle}')
